import log from "../log";
import EnvDetector from "./env_detector";
/**
 * Returns either :
 * - 'null' when the current browser is not Firefox.
 * - '-1' when it is impossible to get the Firefox version
 * - A number above 0 that is the Firefox version number
 * @returns {number|null}
 */
function getFirefoxVersion() {
    if (EnvDetector.browser !== EnvDetector.BROWSERS.Firefox) {
        log.warn("utils", "getFirefoxVersion: Can't access Firefox version. Not a firefox browser.");
        return null;
    }
    const userAgent = navigator.userAgent;
    const match = /Firefox\/([0-9]+)\./.exec(userAgent);
    if (match === null) {
        return -1;
    }
    const result = parseInt(match[1], 10);
    if (isNaN(result)) {
        return -1;
    }
    return result;
}
function getChromeVersion() {
    // TODO: Better Chrome detection?
    if (EnvDetector.browser !== EnvDetector.BROWSERS.Other) {
        log.warn("utils", "getChromeVersion: Can't access Chrome version. Not a Chrome browser.");
        return null;
    }
    const match = navigator.userAgent.match(/Chrome\/(\d+)/);
    if (match !== null) {
        return parseInt(match[1], 10);
    }
    return null;
}
export { getFirefoxVersion, getChromeVersion };
