import RxPlayer from "rx-player";
import receiverEvents from "../const/receiverEvents";
import receiverState from "../const/receiverState";

class RxPlayerReceiverPlayer {
  constructor() {
    this.rxPlayer = null;
    this.mediaManager = null;
    this.castReceiverManager = null;
    this.state = receiverState.IDLE;
  }

  initialize() {
    const videoElement = document.getElementById("receiver-video");

    // Real RxPlayer instance running on the receiver device.
    this.rxPlayer = new RxPlayer({ videoElement });

    this._bindRxPlayerEvents();
    this._initCastReceiver();
  }

  // v2 Cast Receiver API: CastReceiverManager + MediaManager, same manual
  // bridge pattern as the Bitmovin v2 receiver — no CAF playerManager
  // available on this SDK version.
  _initCastReceiver() {
    this.castReceiverManager = cast.receiver.CastReceiverManager.getInstance();

    this.castReceiverManager.onReady(() => {
      this._dispatchToSender(receiverEvents.READY, {});
    });

    this.castReceiverManager.onSenderDisconnected(() => {
      if (this.castReceiverManager.getSenders().length === 0) {
        this.rxPlayer.stop();
      }
    });

    this.mediaManager = new cast.receiver.MediaManager(this.castReceiverManager);

    this.mediaManager.onLoad = this._onLoad.bind(this);
    this.mediaManager.onPlay = this._onPlay.bind(this);
    this.mediaManager.onPause = this._onPause.bind(this);
    this.mediaManager.onStop = this._onStop.bind(this);
    this.mediaManager.onSeek = this._onSeek.bind(this);
    this.mediaManager.onGetStatus = this._onGetStatus.bind(this);

    this.castReceiverManager.start();
  }

  _onLoad(event) {
    const media = event.data.media;
    const customData = event.data.customData || {};

    this._setState(receiverState.LOADING);

    const loadVideoConfig = this._buildLoadVideoConfig(media, customData, event.data.autoplay);

    try {
      this.rxPlayer.loadVideo(loadVideoConfig);
      this.mediaManager.setMediaInformation(media);
      this.mediaManager.broadcastStatus(true);
    } catch (error) {
      this._dispatchToSender(receiverEvents.ERROR, { error: String(error) });
    }
  }

  // Translates the LOAD request + customReceiverConfig-carried drmConfig
  // into RxPlayer's loadVideo() shape. Unlike Bitmovin's declarative
  // LA_URL/headers, RxPlayer's keySystems require an actual getLicense
  // function that performs the license request itself.
  _buildLoadVideoConfig(media, customData, autoplay) {
    const config = {
      url: media.contentId,
      transport: this._mapContentTypeToTransport(media.contentType),
      autoPlay: autoplay !== false,
    };

    if (customData.drmConfig) {
      const drmConfig = JSON.parse(customData.drmConfig);
      config.keySystems = this._buildKeySystems(drmConfig);
    }

    return config;
  }

  _mapContentTypeToTransport(contentType) {
    if (contentType === "application/dash+xml") return "dash";
    if (contentType === "application/x-mpegURL") return "hls";
    if (contentType === "application/vnd.ms-sstr+xml") return "smooth";
    return "dash";
  }

  // Mirrors the same DRM shape your local rxplayer/player.js adapter
  // already builds for non-cast playback — reuse that logic here rather
  // than duplicating it if it's accessible from a shared module.
  _buildKeySystems(drmConfig) {
    const keySystems = [];

    if (drmConfig.widevine) {
      keySystems.push({
        type: "widevine",
        getLicense: (challenge) => this._requestLicense(drmConfig.widevine, challenge),
      });
    }

    if (drmConfig.playready) {
      keySystems.push({
        type: "playready",
        getLicense: (challenge) => this._requestLicense(drmConfig.playready, challenge),
      });
    }

    return keySystems;
  }

  async _requestLicense(drmEntry, challenge) {
    const response = await fetch(drmEntry.laURL, {
      method: "POST",
      headers: {
        "Content-Type": "application/octet-stream",
        ...(drmEntry.requestHeaderKey || {}),
      },
      body: challenge,
    });

    if (!response.ok) {
      throw new Error(`License request failed: ${response.status}`);
    }

    return response.arrayBuffer();
  }

  _onPlay() {
    this.rxPlayer.play();
  }

  _onPause() {
    this.rxPlayer.pause();
  }

  _onStop() {
    this.rxPlayer.stop();
    this._setState(receiverState.IDLE);
  }

  _onSeek(event) {
    const targetTime = event.data.currentTime;
    if (typeof targetTime === "number") {
      this.rxPlayer.seekTo(targetTime);
    }
  }

  _onGetStatus() {
    this.mediaManager.broadcastStatus(true);
  }

  // RxPlayer's playerStateChange fires its own state strings — map them
  // to the shared receiverState/receiverEvents contract, same translation
  // job your local rxplayer/player.js adapter already does for appState.
  _bindRxPlayerEvents() {
    this.rxPlayer.addEventListener("playerStateChange", (state) => {
      switch (state) {
        case "LOADING":
          this._setState(receiverState.LOADING);
          this._dispatchToSender(receiverEvents.LOADING, {});
          break;
        case "PLAYING":
          this._setState(receiverState.PLAYING);
          this._dispatchToSender(receiverEvents.PLAYING, {});
          break;
        case "PAUSED":
          this._setState(receiverState.PAUSED);
          this._dispatchToSender(receiverEvents.PAUSED, {});
          break;
        case "BUFFERING":
        case "SEEKING":
          this._setState(receiverState.BUFFERING);
          this._dispatchToSender(receiverEvents.BUFFERING, {});
          break;
        case "ENDED":
          this._setState(receiverState.ENDED);
          this._dispatchToSender(receiverEvents.ENDED, {});
          break;
        default:
          break;
      }
    });

    this.rxPlayer.addEventListener("error", (error) => {
      this._dispatchToSender(receiverEvents.ERROR, { detail: error });
    });
  }

  _setState(state) {
    this.state = state;
  }

  _dispatchToSender(eventName, detail) {
    if (this.castReceiverManager) {
      this.castReceiverManager.sendCustomMessage(
        "urn:x-cast:com.yourapp.rxplayer.receiver",
        undefined,
        { type: eventName, detail },
      );
    }
  }
}

export default RxPlayerReceiverPlayer;