import config from "../config";
import EnvDetector from "./env_detector";
/**
 * Returns true if the metadata received after a "loadedmetadata" event has
 * to be validated in the current browser (which means that we do not trust
 * this event on these browsers).
 * @returns {boolean}
 */
export default function shouldValidateMetadata() {
    const { FORCE_SHOULD_VALIDATE_METADATA } = config.getCurrent();
    return FORCE_SHOULD_VALIDATE_METADATA || EnvDetector.isSamsungBrowser;
}
